seg = INPUTS["segment"]
lines = [ln.strip() for ln in seg.splitlines() if ln.strip()]
data = {}
for ln in lines:
    if ln.lower().startswith("- city:"):
        data["city"] = ln.split(":", 1)[1].strip()
    elif "forecast condition" in ln.lower():
        data["condition"] = ln.split(":", 1)[1].strip().lower()
    elif "forecast high" in ln.lower():
        # remove trailing F and whitespace
        val = ln.split(":", 1)[1].strip().rstrip("Ff ").strip()
        try:
            data["high_f"] = float(val)
        except:
            data["high_f"] = None

# Ensure condition is one of allowed enums
if data.get("condition") not in {"rain", "sun", "clouds"}:
    # fallback: map common words
    cond = data.get("condition","")
    if "rain" in cond:
        data["condition"] = "rain"
    elif "sun" in cond or "clear" in cond:
        data["condition"] = "sun"
    else:
        data["condition"] = "clouds"

# Craft one-sentence packing tip tailored to the forecast
city = data.get("city", "")
cond = data.get("condition")
high = data.get("high_f")

if cond == "rain":
    tip = f"Pack a compact, waterproof rain jacket or umbrella and quick-dry layers—expect wet conditions despite mild temperatures around {high}°F."
elif cond == "sun":
    tip = f"Bring sunscreen, sunglasses, and a light hat; with highs near {high}°F you'll want sun protection and breathable clothing."
else:  # clouds
    tip = f"Pack a light jacket or sweater and breathable layers—cloudy skies with a high around {high}°F can feel cooler in the morning and evening."

result = {
    "city": city,
    "condition": cond,
    "high_f": high,
    "packing_tip": tip
}

done(result)
